// Included by every C file generated by the 32-bit front end (xlat/x86_32.py): what rc_gen.h is
// for 64-bit guests. Eight registers, eight xmm registers, and the window base in a local (M_),
// so it stays in a host register: a guest store cannot alias it.
#ifndef RC32_GEN_H
#define RC32_GEN_H
#include "rc32.h"
#include "rc_int.h"
#include "rc_sse.h"
#include "rc32_sse.h"
#include "rc32_x87.h"
#pragma clang diagnostic ignored "-Wunused-label"
#pragma clang diagnostic ignored "-Wunused-variable"
#pragma clang diagnostic ignored "-Wunused-but-set-variable"
#pragma clang diagnostic ignored "-Wparentheses-equality"

#ifdef RC_TRACE
void rc_trace_enter(uint64_t addr);
#define RC_ENTER(a) rc_trace_enter(a)
#else
#define RC_ENTER(a) ((void)0)
#endif

int _setjmp(void *) __attribute__((returns_twice));

// -DRC32_KEEP_LOADS (the differential tests): every guest load is a volatile access, so the
// compiler keeps loads whose value is dead, and a load that faults under the reference faults here
// too. Not for the game: it only costs.
#ifdef RC32_KEEP_LOADS
#undef RC_LD
#undef RC_LDS
#undef RC_LDC
#undef RC_LDR
#define RC_LD(T, a) ({ typedef T __attribute__((aligned(1))) _ut; *(const volatile _ut *)(uintptr_t)(a); })
#define RC_LDS(T, a) RC_LD(T, a)
#define RC_LDC(T, a) RC_LD(T, a)
#define RC_LDR(T, a) RC_LD(T, a)
#endif

// host address of guest address g
#define RC_M(g) (M_ + (uint64_t)(uint32_t)(g))

#define XFILL_DECL() rc_v128 x0 = c->x[0], x1 = c->x[1], x2 = c->x[2], x3 = c->x[3], x4 = c->x[4], \
  x5 = c->x[5], x6 = c->x[6], x7 = c->x[7]
#define XFILL() do { x0 = c->x[0]; x1 = c->x[1]; x2 = c->x[2]; x3 = c->x[3]; x4 = c->x[4]; \
  x5 = c->x[5]; x6 = c->x[6]; x7 = c->x[7]; } while (0)
#define XSPILL() do { c->x[0] = x0; c->x[1] = x1; c->x[2] = x2; c->x[3] = x3; c->x[4] = x4; \
  c->x[5] = x5; c->x[6] = x6; c->x[7] = x7; } while (0)
#define FILL_DECL() XFILL_DECL(); const uint64_t M_ = (uint64_t)(uintptr_t)rc_mem; \
  uint64_t rax = c->r[0], rcx = c->r[1], rdx = c->r[2], rbx = c->r[3], rsp = c->r[4], \
  rbp = c->r[5], rsi = c->r[6], rdi = c->r[7]
#define FILL() do { rax = c->r[0]; rcx = c->r[1]; rdx = c->r[2]; rbx = c->r[3]; rsp = c->r[4]; \
  rbp = c->r[5]; rsi = c->r[6]; rdi = c->r[7]; XFILL(); } while (0)
#define SPILL() do { c->r[0] = rax; c->r[1] = rcx; c->r[2] = rdx; c->r[3] = rbx; c->r[4] = rsp; \
  c->r[5] = rbp; c->r[6] = rsi; c->r[7] = rdi; XSPILL(); } while (0)

// Calls: every register goes through rc_ctx (32-bit MSVC code with whole-program optimisation
// may use custom conventions between its own functions, so nothing is assumed).
#define SPILL_CALL() SPILL()
#define FILL_CALL() FILL()
#define SPILL_RET() SPILL()

// Returns: every `ret` records the address it pops (c->ret_to), and every call site compares it
// with its own return address. A C return always goes back to the C caller, whatever the guest
// stack says; hand-written code (the CRT's x87 math) also returns two levels at once
// (`pop eax; ret` in a callee). On a mismatch the caller returns at once (the registers are in
// rc_ctx already), and so on up, until the frame whose call site the guest returned to: what the
// guest does. A native -> guest call (rc32_call) fails when its sentinel does not come back.
#define RC32_RET_SAVE() (c->ret_to = RC_LDS(uint32_t, RC_M(rsp)))
#define RC32_RET_OTHER(a) __builtin_expect(c->ret_to != (a), 0)

#endif
